// Себестоимость и экономия масштаба: из чего она складывается и сколько стоила бы машина при большем выпуске
function costHTML(md,s){if(md.status!=='prod')return '';const v=Math.max(1,modelVol(md)),mat=matCost(md,s),lab=hoursPerCar(md,s)/hoursPerWorker(s)*wageNow(s),at=k=>unitCost({...md,vol:v*k},s),l=1-labLearn(md);
  return `<p class="small muted" style="margin-top:6px">Себестоимость ${money(mat+lab)} = детали ${money(mat)} + работа ${money(lab)} при выпуске ≈ ${fmtD(v)} в месяц. <span class="good">Больше выпуск — дешевле машина:</span> при ${fmtN(v*3)} в месяц — ${money(at(3))}, при ${fmtN(v*10)} — ${money(at(10))}${l>0.02?`. Опыт рабочих: ${fmtN(md.made||0)} машин уже собрано — работы на ${Math.round(l*100)}% меньше`:''}.</p>`;}
// 0.26: грузовик — для каких перевозок он годится: цена тонно-километра против эталона соперников и кто его взял
function cpkTxt(x){if(!isFinite(x)||x<=0)return '—';if(x<0.1)return (Math.round(x*1000)/10).toString().replace('.',',')+'¢';if(x<1)return Math.round(x*100)+'¢';return '$'+x.toFixed(2).replace('.',',');}
function truckHint(md,s){if(!isTruck(md)||md.status==='off')return '';const c=s.country,PT=prefP('truck',c,s),U=md.useD||{},tot=TUSE.reduce((a,u)=>a+(U[u]||0),0),sh=truckUseSh(c,s);
  const rows=TUSE.filter(u=>sh[u]>0.005).map(u=>{const ref=truckRef(u,s.y),cR=truckCost(ref,u,c,s,PT*payK(ref)).cpk,cM=truckCost(md,u,c,s,md.price).cpk,r=cR/cM,tone=r>=1.05?'good':r<0.9?'bad':'muted';
    return `<tr><td>${TRUCK_USE[u].n}<small class="muted"> · ${esc(TRUCK_USE[u].who)}</small></td><td class="n ${tone}">${cpkTxt(cM)}</td><td class="n muted">${cpkTxt(cR)}</td><td class="n">${md.status==='prod'&&tot>0?pct((U[u]||0)/tot,0):'—'}</td></tr>`;}).join('');
  return `<div class="label" style="margin-top:10px">Тонно-километр: во что обходится перевозка</div><table class="pl ptab ctab" style="margin-top:4px"><tr><th>Перевозки</th><th class="n">Ваша</th><th class="n">Соперники</th><th class="n">Берут</th></tr>${rows}</table>
    <p class="small muted" style="margin-top:4px">Фирма считает всё: машину за годы службы, ремонт и простои, бензин, шофёра — и сколько тонн машина перевезёт за день. Фургон хорош для развозки по району, полуторатонка — по городу, трёхтонка — между городами: одна машина другую не заменяет. «Берут» — кто купил вашу машину в прошлом месяце.</p>`;}
function stockWarn(md){return md.status==='prod'&&md.stock>Math.max(3,(md.fc||0)*3);}
// Сворачиваемые разделы: длинные списки открываются, когда нужны
